import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Max Crocombe', position: 'GK', age: 32, club: 'Millwall', bio: { "es": "Maxime Teremoana Crocombe, de ascendencia de las Islas Cook, nació en Auckland antes de mudarse a Inglaterra cuando era joven. Fue el hombre entre los palos en la temporada ganadora de la Liga Nacional Norte de Salford City en 2017/18; su forma le valió un debut nacional con los All Whites en un amistoso contra Canadá en 2018, el primero de más de 20 partidos internacionales hasta la fecha. Fue una fuerza clave para Grimsby Town cuando se convirtió en el primer equipo de la historia en eliminar a cinco equipos de divisiones superiores en una sola temporada de la Copa FA, alcanzando los cuartos de final en 2023. En total, ha estado en 10 clubes en el Reino Unido antes de triunfar con Millwall en el campeonato y fue el portero titular en la Navidad de 2025. En el camino, ha pasado mucho tiempo en el banquillo. \"Realmente no soy alguien que se enfurruña por eso\", le dijo a la BBC. \"Siempre creo que jugaré\". Ha ganado dos veces el Guante de Oro en torneos internacionales y ha conservado la confianza del entrenador en jefe de los All Whites, Darren Bazeley. Ha sido nominado por tener las mejores bromas del equipo, lo que llevó a su compañero All White Ben Waine a decir: \"a veces tiene humor seco, pero es bastante divertido\".", "en": "Of Cook Islands heritage, Maxime Teremoana Crocombe was born in Auckland before moving to England as a youngster. He was the man between the sticks in Salford City’s National League North winning season in 2017/18 – his form earning him a national debut for the All Whites in a friendly against Canada in 2018, the first of more than 20 international caps to date. He was a key force for Grimsby Town when it became the first team in history to eliminate five teams from higher divisions in a single FA Cup season, reaching the quarter-finals in 2023. In total, he has been at 10 clubs in the UK before cracking it with Millwall in the Championship and was first choice keeper by Christmas 2025. Along the way there’s been plenty of time on the bench. “I’m not really one to sulk about it,” he told the BBC. “I always believe I will play.” He’s twice earned the Golden Glove award at international tournaments and has retained All Whites head coach Darren Bazeley’s trust. He’s been nominated as having the best banter in the squad, leading fellow All White Ben Waine to say: “sometimes it’s dry humour but he is quite funny.”" } },
  { number: 12, name: 'Alex Paulsen', position: 'GK', age: 24, club: 'Bournemouth', bio: { "es": "Paulsen es un talento especial que busca desplazar a Max Crocombe por el puesto número uno en los All Whites. Su contrato de cuatro años con Bournemouth - \"Un gran momento para mí y mi familia\" - cuando tenía sólo 21 años lo convirtió en uno de los pocos kiwis en conseguir un contrato de la Premier League. \"La intensidad y la diferencia en cómo entrenan es muy competitiva\", dijo al podcast Unused Subs. Los Cherries, sin duda impresionados por su agilidad y reflejos, lo ven como un proyecto a largo plazo y primero fue cedido al Auckland FC, donde fue fundamental para que se convirtieran en \"Premiers\" en su primera temporada en la A-League, y al Lechia Gdańsk. Su actitud, técnica y pases son insuperables, dice su compañero de equipo All White, Ben Old. Old recuerda la vez que su mejor amigo estaba grabando en video sus habilidades de malabarismo en su nuevo teléfono y una pelota golpeó el teléfono y salió volando por un pequeño espacio en la ventana de su habitación de hotel en el piso 13. \"Lo primero que pensé fue que mi madre me iba a matar\", dijo Paulsen al sitio web The Unused Subs.", "en": "Paulsen is a special talent, who is seeking to displace Max Crocombe for the No 1 position in the All Whites. His four-year deal with Bournemouth - “A big moment for me and my family,” – when he was just 21 made him one of very few Kiwis to clinch a Premier League deal. “The intensity and the difference in how they train is just so competitive,” he told the Unused Subs podcast. The Cherries, no doubt impressed by his agility and reflexes, see him as a long-term project and he went on loan first to Auckland FC, where he was pivotal in them becoming “Premiers” in their first season in the A-League, and Lechia Gdańsk. His attitude, technique and passing are second to none, his All White teammate Ben Old Says. Old recalls the time his best mate was videoing his juggling skills on his new phone and a ball hit the phone which sailed out a small gap in the window of his 13th floor hotel room. “My first thought was, my mum’s gonna kill me,” Paulsen told The Unused Subs website." } },
  { number: 22, name: 'Michael Woud', position: 'GK', age: 27, club: 'Auckland FC', bio: { "es": "Woud se ha enfrentado a muchos obstáculos en su carrera, incluido pasar 620 días sin un partido profesional. A pesar de ser el primer fichaje de su recién creado club de Auckland, rápidamente fue enviado a la banca en favor de su compañero All White Alex Paulsen. \"Fue difícil y hubo algunos momentos oscuros\", dijo al podcast The Unused Subs.  Cuando era adolescente, Woud dejó Nueva Zelanda después de fichar por el Sunderland, pero nunca llegó más allá de la academia. También pasó por Holanda y Japón y su suerte ha cambiado este año: está destinado a la Copa del Mundo como tercer portero gracias a la lesión de otro contendiente, Oli Sail.", "en": "Woud has faced many obstacles in his career, including going 620 days without a professional match. Despite being the first signing for his newly established Auckland club he was promptly benched in favour of fellow All White Alex Paulsen. “It was tough and there were some dark moments,” he told The Unused Subs podcast.  As a teen Woud left NZ after signing for Sunderland but never made it further than the academy. There were spells in the Netherlands and Japan too and his luck has changed this year - he’s World Cup bound as the third choice keeper thanks to an injury to another contender Oli Sail." } },
  // Defensores
  { number: 2, name: 'Tim Payne', position: 'DF', age: 31, club: 'Wellington Phoenix', bio: { "es": "Payne, uno de los primeros nombres en formar parte del once inicial de los All Whites, es valorado por su versatilidad. Puede ocupar tanto el puesto de central como el de mediocampo defensivo, aunque su posición principal es la de lateral derecho. \"Su experiencia es fenomenal, puede jugar en muchas posiciones en la línea de fondo\", dijo uno de sus entrenadores en Phoenix. Hizo su debut con los All Whites con solo 18 años en 2012 y el mismo año jugó en el equipo de Nueva Zelanda en los Juegos Olímpicos de Londres. Su mejor oportunidad parecía ser firmar con Blackburn Rovers, pero los problemas de visa de trabajo limitaron sus apariciones a nivel de grupos de edad y, aparte de una temporada con los Portland Timbers en los EE. UU., se ha quedado principalmente con el Wellington Phoenix, disputando más de 150 apariciones con ellos en la A-League. En vísperas del torneo, se convirtió en una estrella de las redes sociales después de que un influencer de Argentina llamara a sus seguidores a unirse y convertir al poco conocido jugador de 32 años en un “héroe” de la próxima Copa del Mundo.", "en": "One of the first names to go on the All Whites starting XI, Payne is valued for his versatility. He can fill in at both centre back and defensive midfield, although his main position is that of right-back. “His experience is phenomenal, he can play in a lot of positions across the backline,” one of his Phoenix coaches said. He made his All Whites debut at just 18 in 2012 and the same year played in NZ’s team at the London Olympics. His best break seemed to be signing with Blackburn Rovers but work visa problems limited his appearances at age-group level and, apart from a season with the Portland Timbers in the US, he has mainly stayed with the Wellington Phoenix, making more than 150 appearances for them in the A-League. On the eve of the tournament he became a social media star after an influencer from Argentina called on his followers to unite and make the little-known 32-year-old a “hero” of the upcoming World Cup." }, special: "Social media star" },
  { number: 3, name: 'Francis de Vries', position: 'DF', age: 31, club: 'Auckland FC', bio: { "es": "De Vries es valorado no sólo por sus destacadas habilidades defensivas sino también por la actitud firme y la tutoría que aporta al equipo. Ha pasado por el equipo Vancouver Whitecaps de la MLS y el club sueco Värnamo, pero también ha tenido contratiempos, lo que lo llevó a leer sobre psicología deportiva. Él atribuye el desarrollo de habilidades mentales a su rendimiento en el campo de fútbol y ha creado una empresa para ayudar a los jugadores jóvenes en esta área. “El fútbol es un maestro de habilidades que te ayudarán en todas las áreas de tu vida”, dijo al podcast The Unused Subs. \"El fútbol tiene que significar algo más que resultados: de ahí es de donde vienen la verdadera realización y las verdaderas conexiones\". La filosofía está dando sus frutos en Auckland, donde los aficionados lo eligieron Jugador de la Temporada 2024-25 y para los All Whites, donde es titular habitual.", "en": "De Vries is valued not only for his outstanding defensive skills but also the grounded attitude and mentoring he brings to the squad. He’s had spells with MLS side Vancouver Whitecaps and Swedish club Värnamo but there’ve been setbacks too, prompting him to read up on sports psychology. He credits developing mental skills as helping his performance on the football pitch and has set up a business to help young players in this area. “Football is a teacher of skills that will help you in all areas of your life,” he told The Unused Subs podcast. “Football has to mean something more than results – that’s where real fulfilment, real connections come.” The philosophy is paying dividends in Auckland where fans chose him as Player of the Season in 2024-25 and for the All Whites where he is a regular starter." }, special: "Psychology buff" },
  { number: 4, name: 'Tyler Bindon', position: 'DF', age: 21, club: 'Sheffield United', bio: { "es": "Bindon está siguiendo los pasos de Jenny, su ex portera de Football Ferns, al representar a Nueva Zelanda en una Copa del Mundo. Cuando era niño, Bindon era un elemento habitual al margen de las sesiones de entrenamiento de los Ferns. Su padre, Grant Bindon, es ex capitán de voleibol de Nueva Zelanda y conoció a Jenny cuando eran estudiantes en Illinois. Bindon pasó por el sistema de la Major League Soccer pero optó por los All Whites a pesar de atraer el interés de los seleccionadores estadounidenses en la categoría Sub-19. Se cree que Tyler y Jenny son el primer dúo de madre e hijo en jugar al fútbol en los Juegos Olímpicos. El ex capitán de los All White, Ryan Nelsen, cree que Bindon “cumple todos los requisitos” para tener éxito en la Premier League (firmó con Nottingham Forest y pasó la temporada 2025-26 cedido en Sheffield United) y se convertirá en el mejor jugador de la historia de Nueva Zelanda. \"Tiene todas las cualidades necesarias, incluida su calma bajo presión cuando tiene el balón\", dice. Una amenaza goleadora en la jugada a balón parado, y saltó alto para rematar de cabeza desde una esquina para su primer gol en el Sheffield United con sus padres de Nueva Zelanda en las gradas.", "en": "Bindon is following in his former Football Ferns goalkeeper mum Jenny’s footsteps by representing NZ at a World Cup. As a child Bindon was a common fixture on the sidelines of the Ferns’ training sessions. His dad, Grant Bindon, is a former New Zealand volleyball captain and met Jenny while they were students in Illinois. Bindon came through the Major League Soccer system but opted for the All Whites despite attracting interest from the US selectors at Under-19 level. It is believed Tyler and Jenny are the first mother and son duo to play football at the Olympics. Former All White captain Ryan Nelsen believes Bindon “ticks every box” to succeed in the Premier League (he has signed with Nottingham Forest and spent the 2025-26 season on loan at Sheffield United) and will go on to become New Zealand’s best ever player. “He’s got all the qualities needed, including his calmness under pressure when on the ball, he says. A goalscoring threat at the set-piece – and leapt high to head home from a corner for his first goal at Sheffield United with his parents over from NZ in the stands." }, special: "Mr Calm" },
  { number: 5, name: 'Michael Boxall', position: 'DF', age: 36, club: 'Minnesota United', bio: { "es": "Después de nueve años en Minnesota, es el líder de todos los tiempos en aperturas y apariciones y es una figura clave en su línea defensiva. Dice que está esperando a que todos los jóvenes pasen corriendo junto a él, pero \"todavía estoy esperando\". Los comentaristas elogian su “enorme presencia física” y su capacidad de liderazgo, pero no le gusta la temporada baja y el entrenamiento en solitario que requiere. \"Vas a lugares oscuros y yo simplemente pienso en algunas formas creativas de seguir adelante\", dice. Boxall, de ascendencia samoana, fue una vez blanco de abusos raciales durante un partido contra Qatar en Austria. Esto llevó a que los All Whites se negaran a jugar la segunda parte y también presentaran una denuncia ante la FIFA. \"Estoy orgulloso de mis compañeros de equipo por adoptar la postura que adoptaron\". Después de 55 apariciones con los All Whites sin anotar, anotó uno en la victoria de Nueva Zelanda por 3-0 sobre Nueva Caledonia para ayudar al equipo a clasificarse para esta Copa del Mundo. Dato curioso: colecciona calzado deportivo. \"Tengo unas cuantas Nike raras y también unas cuantas Jordan que sólo uso cuando no llueve ni nieva\", dice.", "en": "After nine years at Minnesota he is the all-time leader for starts and appearances and is a key figure in its backline. He says he is waiting for all the young guys to run past him, but “I’m still waiting”. Commentators praise his “massive physical presence” and his leadership skills, however, he does not like the off-season and the solo training it requires. “You go to some dark places and I just think of some creative ways to keep me going,” he says. Boxall, who is of Samoan heritage, was once the target of racial abuse during a match against Qatar in Austria. It led to the All Whites refusing to play the second half and they also filed a complaint with Fifa. “I’m proud of my teammates for taking the stand they did.” After 55 appearances for the All Whites without scoring he bagged one in NZ’s 3-0 win over New Caledonia to help the side qualify for this World Cup. Fun fact: He collects sports shoes. “I’ve got a few rare Nikes and a few Jordans as well that I only bust out when it’s not raining or snowing,” he says" }, special: "Trainers aficionado" },
  { number: 13, name: 'Liberato Cacace', position: 'DF', age: 25, club: 'Wrexham', bio: { "es": "Cacace es un All White clave, y fue nombrado capitán suplente durante el descanso forzado por lesión de Chris Wood. Está construyendo una carrera que comenzó cuando era adolescente en el Wellington Phoenix antes de atraer la atención del club belga Sint-Truiden. Eso lo llevó a cuatro temporadas con el club Empoli de la Serie A italiana, el primer neozelandés en jugar en la Serie A, para deleite de su padre, que es de Nápoles y presentó a su hijo al fútbol cuando solo tenía tres años. El fichaje de Cacace con Wrexham atrajo una gran publicidad en casa debido a la popularidad de la serie de televisión; sin embargo, una racha de lesiones ha dificultado el comienzo. Dato curioso: el padre de Cacace brindó por el acuerdo con el entrenador del Wrexham, Phil Parkinson, y otros directivos del club cuando visitaron su restaurante en Wellington, mientras el equipo se preparaba para un amistoso contra el Phoenix.", "en": "Cacace is a key All White, being named as a stand-in captain during Chris Wood’s injury-enforced layoff. He is building on a career that began as a teen at the Wellington Phoenix before attracting the attention of Belgian club Sint-Truiden. That led to four seasons with Italian Serie A club Empoli – the first Kiwi to play in Serie A, much to the delight of his dad, who is from Naples and introduced his son to football when he was just three years old. Cacace’s signing with Wrexham attracted huge publicity at home due to the popularity of the TV series, however, a run of injuries has made for a difficult start. Fun fact: Cacace’s dad toasted the deal with the Wrexham manager, Phil Parkinson, and other club officials when they visited his restaurant in Wellington, as the side was preparing for a friendly against the Phoenix." }, special: "Influential" },
  { number: 15, name: 'Nando Pijnaker', position: 'DF', age: 27, club: 'Auckland FC', bio: { "es": "De ascendencia holandesa, Pijnaker ha jugado en Suecia, Suiza, Portugal, Dinamarca e Irlanda, antes de regresar a Nueva Zelanda para unirse al nuevo club de la A-League, el Auckland FC, en 2024. Su experiencia irlandesa fue destacada. Se unió a Sligo Rovers, que recuerda que está “en medio de la nada y tiene un clima terrible durante todo el año”. Sin embargo, esto fue compensado por gente \"increíble\", que dio la bienvenida a Pinjaker y a su compañero All White Max Mata, le dijo a WaiBOP Football. Hizo 77 apariciones con Sligo. Dato curioso: la camiseta que usó Pijnaker cuando anotó el gol de la victoria en el minuto 97 en el partido de Auckland contra el Sydney FC se exhibe en el Museo de Auckland y representa la exitosa primera temporada del club en la A-League.", "en": "Of Dutch heritage, Pijnaker has played in Sweden, Switzerland, Portugal, Denmark and Ireland, before returning to New Zealand to join new A-League club Auckland FC in 2024. His Irish experience was a standout. He joined Sligo Rovers, which he recalls as being “in the middle of nowhere and it has terrible weather all year round”. However, this was offset by “amazing” people, who welcomed Pinjaker and fellow All White Max Mata, he told WaiBOP Football. He made 77 appearances for Sligo. Fun fact: The jersey Pijnaker wore when he scored the winning goal in the 97th minute in Auckland’s match against Sydney FC is on display at Auckland Museum, representing the club’s hugely successful first season in the A-League." } },
  { number: 16, name: 'Finn Surman', position: 'DF', age: 22, club: 'Portland', bio: { "es": "Después de un comienzo lento, Surman se destacó en la temporada 2025 de los Timbers y fue nombrado Jugador del Año por los fanáticos. Le encanta la oportunidad de aprender del ex jugador de Inglaterra y ahora entrenador del club, Phil Neville. \"Es una persona muy entusiasta... Me pone un poco nervioso\", dijo al podcast The Unused Subs. El defensa de 1,90 m también está impresionado con la liga y califica su intensidad, estilo y velocidad de los atacantes como un gran paso adelante respecto a lo que estaba acostumbrado en la A-League. Surman se fue de casa a los 15 años para perfeccionar sus habilidades futbolísticas, pero los nervios iniciales se calmaron cuando descubrió que vivir en el albergue de una academia en Wellington \"era como una pijamada masiva y prolongada\".  Ha dejado su huella a nivel de grupos de edad, incluido el capitán de los All Whites en la Copa Mundial Sub-20 de la FIFA 2023, pero esas cosas quedarán eclipsadas si consigue algo de tiempo de juego en “la cima del fútbol”. Dato curioso: a Surman le impresiona que un aficionado con una motosierra corte un trozo de tronco para presentárselo a cada uno de los goleadores del equipo en los partidos de Portland; tallar una mesa de café es el plan si logra ganársela.", "en": "After a slow start Surman was outstanding in the Timbers’ 2025 season and named as fans’ Player of the Year. He relishes the chance to learn from former England player and now the club’s head coach, Phil Neville. “He’s a very enthusiastic person … It gees me up a bit,” he told The Unused Subs podcast. The 1.90m defender is impressed with the league too, rating its intensity, flair and attackers’ speed as a big step up from what he was used to in the A-League. Surman left home at 15 to sharpen his football skills but any initial nerves were eased when he discovered living at an academy hostel in Wellington “was like a massive extended sleepover”.  He’s made his mark at age-group level, including captaining the All Whites at the 2023 Fifa Under-20 World Cup, but these will be eclipsed by getting some game time at “the pinnacle of football”. Fun fact: Surman is impressed that a fan with a chainsaw cuts off a piece of log to present to each of the team’s goalscorers at Portland’s matches – carving a coffee table is the plan if he manages to earn one." } },
  { number: 24, name: 'Callan Elliot', position: 'DF', age: 26, club: 'Auckland FC', bio: { "es": "Elliot comenzó como atacante y se transformó en defensor en parte porque vio escasez en su club. Se describe a sí mismo como un defensa de \"estilo moderno\" al que le gusta ir hacia adelante. Después de comenzar en el Wellington Phoenix, fichó cedido por el Xanthi griego y luego por el Motherwell, pero no fueron tiempos felices. Le contó a Stuff sobre los descansos en su carrera cuando no tenía tiempo de juego o no tenía un club: \"Períodos como esos apestan, pero al final del día, jugar al fútbol sigue siendo lo que quiero hacer, así que eso me mantiene adelante\". Para los All Whites es el respaldo de Tim Payne y Storm Roux. Dato curioso: nacido en Escocia, le encanta Edimburgo. \"Creo que es un lugar hermoso. Siempre le digo a la gente que si llegas a Edimburgo en un día soleado, es absolutamente increíble\", le dijo a la BBC.", "en": "Elliot started as an attacker and morphed into a defender in part because he saw shortages at his club. He describes himself as a &quot;modern-style&quot; fullback who likes to get forward. After starting out at the Wellington Phoenix, he signed for Greek side Xanthi and then Motherwell on loan but they weren’t happy times. He told Stuff about breaks in his career when he hasn’t got game time or didn’t have a club: “Periods like those suck, but at the end of the day, playing football is still what I want to do, so that keeps me going.” For the All Whites he’s a back-up to Tim Payne and Storm Roux. Fun fact: Scottish-born, he loves Edinburgh. “I just think it’s a beautiful place. I always say to people if you get Edinburgh on a sunny day, it’s absolutely unbelievable,” he told the BBC." } },
  { number: 26, name: 'Tommy Smith', position: 'DF', age: 34, club: 'Braintree Town', bio: { "es": "Sólo Smith y el capitán Chris Wood quedan del equipo de 2010 que fue a la Copa del Mundo en Sudáfrica. El entrenador Darren Bazeley, ahora quinto defensa central, califica sus valores y liderazgo: “Tommy ha sido muy fuerte en ese espacio”. Smith, mientras tanto, dijo al podcast The Unused Subs: \"Los centrales que están por delante de mí en el orden jerárquico [para los All Whites] están jugando a un nivel fantástico, y mis minutos probablemente serán limitados, y eso está bien. He llegado a un acuerdo con eso\". Ha sido una carrera distinguida para un hombre al que una vez le dijo la leyenda del Manchester United, Roy Keane: “Mi abuela podría haber corrido más rápido que tú y está muerta”. La pareja cruzó espadas en Ipswich cuando Keane era un entrenador \"intimidante\". Sin embargo, fue Keane quien animó a Smith, nacido en Inglaterra, a cambiar su lealtad a Nueva Zelanda y dice que nunca se ha arrepentido. El ex capitán de los All Whites, Ryan Nelsen, cree que fue sólo la mala suerte lo que impidió que Smith fichara por un club de la Premier League. \"Jugué junto a jugadores que no eran tan buenos como Tommy\", dice. Después de una exitosa temporada con el Auckland, Smith juega en la quinta división inglesa por motivos familiares.", "en": "Only Smith and captain Chris Wood remain from the 2010 squad that went to the World Cup in South Africa. Now the fifth-choice centre back, coach Darren Bazeley rates his values and leadership: “Tommy has been very strong in that space.” Smith, meanwhile, told The Unused Subs podcast: “The centre-backs who are ahead of me in the pecking order [for the All Whites] are playing at a fantastic level, and my minutes are probably going to be limited, and that’s fine. I’ve come to terms with that.” It has been a distinguished career for a man once told by Manchester United legend Roy Keane: “My nan could have run faster than you and she’s dead.” The pair crossed swords at Ipswich when Keane was an “intimidating” manager. However, it was Keane who encouraged English-born Smith to switch his allegiance to NZ and he says he has never regretted it. Former All Whites skipper Ryan Nelsen believes it was only bad luck that stopped Smith from signing for a Premier League club. “I played alongside players who weren’t as good as Tommy,” he says. After a successful season with Auckland, Smith is playing in the English fifth tier for family reasons." }, special: "Experienced" },
  // Volantes
  { number: 6, name: 'Joe Bell', position: 'MF', age: 27, club: 'Viking', bio: { "es": "En un equipo con nombres de estrellas en ambos extremos del campo, Bell está más que contento con un papel en las sombras, como dijo a Fifa.com. \"No me gusta ser el centro de atención, así que creo que es muy agradable estar sentado entre los que marcan y los que salvan goles y es un papel importante en el equipo. Obviamente, jugando en el centro del campo, hay mucha responsabilidad de ser bueno tanto en ataque como en defensa, pero especialmente con el balón. Eso es lo que más disfruto del juego, tener el balón en mis pies\". Bell se relajó en su casa en Wānaka, en Central Otago, durante el verano, después de haber ayudado a su club noruego, el Viking, a poner fin a una sequía de títulos de liga de 34 años en la que los aficionados, incluido un ministro del gabinete, invadieron el campo. También metió a su club en la clasificación de la Liga de Campeones, por lo que podría “cumplir algunos de los dos requisitos más importantes que se pueden cumplir” en 2026. Bell, calificado por su club por ser bueno en duelos individuales y tener confianza en el balón, aspira a un puesto titular cuando llegue la Copa del Mundo, pero dice que “apoyar y ayudar al equipo” es lo más importante: una actitud sensata por parte de un hombre cuyo segundo nombre es Zen.", "en": "In a squad with star names at both ends of the pitch, Bell is more than content with a role in the shadows, as he told Fifa.com. “I don’t like to be in the spotlight, so I think it’s quite nice to sit there between those who score and those who save goals and it’s an important role in the team. Obviously, playing in the centre of the pitch, there’s a lot of responsibility to be good both in attack and in defence, but especially with the ball. That’s what I enjoy the most about the game, having the ball at my feet.” Bell relaxed at home in Wānaka in Central Otago over the summer having helped his Norwegian club side Viking end a 34-year league title drought which saw fans, including a cabinet minister, invade the pitch. It got his club into Champions League qualifying as well so he could be “ticking some of the two biggest boxes you can tick” in 2026. Rated by his club for being good in individual duels and confident on the ball, Bell is aiming for a starting place come World Cup time but says “supporting and helping the team” is most important – a sensible attitude from a man whose middle name is Zen." }, special: "All-round midfielder" },
  { number: 7, name: 'Matt Garbett', position: 'MF', age: 24, club: 'Peterborough United', bio: { "es": "El entrenador, Darren Bazeley, apoyó a Garbett cuando lo despidió el club holandés NAC Breda, admirando su “actitud súper competitiva” y describiéndolo ante Stuff como “un gran muchacho, con una gran actitud”. Se espera que Garbett sea un miembro clave del equipo de la Copa del Mundo y había estado en buena forma para su nuevo club esta temporada hasta que una grave lesión en el pie lo dejó fuera. Anteriormente dijo que mudarse a Inglaterra, donde nació, era “justo lo que necesitaba”.  El entrenador de Peterborough, Darren Ferguson, se mostró satisfecho con su habilidad en el centro del campo y dijo que era “una presencia imperdible en los entrenamientos con su ritmo de trabajo y su voluntad de disparar”. Garbett ha representado a Nueva Zelanda en varios niveles de grupos de edad antes de ser capitán del OlyWhites (Sub-23) en los Juegos Olímpicos de París 2024.", "en": "The coach, Darren Bazeley, stuck by Garbett when he was let go by Dutch club NAC Breda, admiring his “super competitive attitude” and describing him to Stuff as “a great lad, with a great attitude”. Garbett is expected to be a key member of the World Cup squad and had been in good form for his new club this season until a serious foot injury sidelined him. Previously he said the move to England, where he was born, was “just what I needed”.  The Peterborough manager, Darren Ferguson, was pleased with his ability in midfield and said he was “an unmissable presence at trainings with his work rate and willingness to have a shot”. Garbett has represented NZ at various age-group levels before captaining the OlyWhites (Under-23s) at the 2024 Paris Olympics." } },
  { number: 8, name: 'Marko Stamenić', position: 'MF', age: 24, club: 'Swansea City', bio: { "es": "Uno de los jugadores más importantes de la mezcla de los All Whites por su físico y capacidad técnica y el entrenador, Darren Bazeley, admira la “consistencia dentro y fuera de la posesión” del centrocampista. Bazeley dijo al NZ Herald: \"Es tácticamente muy astuto\". Stamenić quiere ayudar a los All Whites a “lograr logros en los que probablemente nadie haya pensado con el Mundial y hasta dónde podemos llegar”. En tres años ha levantado trofeos en Dinamarca, Serbia y Grecia. Un punto culminante de su carrera fue la oportunidad de vivir en el país de origen de su padre, Serbia, y absorber su cultura, comida y celebraciones. \"He conocido a muy pocos serbios de Samoa... me sentí muy especial. Me encanta abrazar ambas culturas...\" Dato curioso: su madre una vez hizo 30 guirnaldas (guirnaldas) de chocolate Ferrero Rocher para los All Whites y se las regaló a los jugadores después de un partido contra Samoa.", "en": "One of the most important players in the All Whites mix for his physicality and technical ability with the head coach, Darren Bazeley, admiring the midfielder’s “consistency in and out of possession”. Bazeley told the NZ Herald: “He’s tactically very astute.” Stamenić wants to help the All Whites “make achievements that probably no one has thought about with the World Cup and how far we can actually go”. In a three-year spell he has lifted trophies in Denmark, Serbia and Greece. A career highlight was the chance to live in his dad’s home country, Serbia, and absorb its culture, food and celebrations. “I’ve met very few Samoan-Serbs …it felt quite special. I love embracing both cultures …” Fun fact: His mum once made 30 Ferrero Rocher chocolate leis (garlands) for the All Whites and presented them to the players after a match against Samoa." } },
  { number: 10, name: 'Sarpreet Singh', position: 'MF', age: 27, club: 'Backa Topola', bio: { "es": "Singh fue titular en los 10 partidos internacionales de Nueva Zelanda en 2025 y será una fuerza clave en la Copa del Mundo si se recupera de una importante lesión en la rodilla. Su fichaje por el Bayern de Múnich en 2019 causó una gran expectación en casa, pero no pudo entrar en el primer equipo y siguieron temporadas en otros clubes europeos. Pasó la primera mitad de 2026 en Phoenix, donde comenzó su carrera, cedido por el club serbio Backa Topola. Nacido en Auckland de padres indios que emigraron desde Punjab, Singh se convertirá en el segundo jugador de origen indio en la Copa del Mundo en sus casi 100 años de historia. \"Haré lo mejor que pueda porque sé que represento a mucha gente. Quiero intentar crear un camino para los futuros jugadores indios\", dijo a The Times of India. \"Nuestro objetivo [en el Mundial] es salir de la fase de grupos, y no creo que tengamos que cambiar demasiado [para lograrlo]\".", "en": "Singh started all 10 of New Zealand’s internationals in 2025 and will be a key force in the World Cup if he recovers from a major knee injury. His signing for Bayern Munich in 2019 caused huge excitement at home but he could not break into the first team and stints with other European clubs followed. He spent the first half of 2026 back at Phoenix, where his career began, on loan from Serbian club Backa Topola. Born in Auckland to Indian parents who migrated from Punjab, Singh will become only the second Indian-origin player at the World Cup in its almost 100-year history. “I will do my best because I know I represent a lot of people. I want to try and create a pathway for future Indian players,” he told The Times of India. “Our goal [at the World Cup] is to get out of the group stage, and I don’t think we have to change too much [to achieve that].”" } },
  { number: 14, name: 'Alex Rufer', position: 'MF', age: 29, club: 'Wellington Phoenix', bio: { "es": "Rufer pertenece a la realeza del fútbol neozelandés: su padre Shane es un ex All White, mientras que su tío Wynton ganó cuatro títulos con el Werder Bremen y fue nombrado Futbolista del Siglo de Oceanía. Alex es el jugador con más años de servicio en su club, ya que debutó a los 17 años y en 2024 su liderazgo, su capacidad para ganar balones y su distribución lo llevaron a ser nombrado en el equipo masculino de la temporada de la PFA A-League. Dato curioso: toda su familia es fanática de la pesca y las cañas generalmente están en la parte trasera del auto, le dijo al podcast The Unused Subs. \"De hecho, se convirtió en algo que me distrajo del fútbol y de las presiones que conlleva\".", "en": "Rufer is from Kiwi football royalty – his dad Shane is a former All White while uncle Wynton won four titles with Werder Bremen and was named the Oceania Footballer of the Century. Alex is his club’s longest serving player having debuted as a 17-year-old and in 2024 his leadership, ball-winning ability, and distribution led to him being named in the PFA A-League men’s team of the season. Fun fact: His family are all fishing fans and the rods are usually in the back of the car, he told The Unused Subs podcast. “It actually became something that took my mind away from football and the pressures of that.”" }, special: "Keen fisher" },
  { number: 23, name: 'Ryan Thomas', position: 'MF', age: 31, club: 'PEC Zwolle', bio: { "es": "Posiblemente el jugador neozelandés más talentoso de una generación, ha tenido una carrera arruinada por lesiones de rodilla, lo que le llevó a una cirugía espantosa que requirió que le rompieran las rodillas y las bajara. Tenía solo 19 años cuando debutó con los All Whites y también jugó en el PEC Zwolle cuando era adolescente, anotando dos goles en la sorprendente derrota por 5-1 sobre el Ajax en la final de la Copa de Holanda de 2014. Se mudó al PSV Eindhoven pero en su primera semana se rompió el ligamento anterior cruzado. Fuera de la selección nacional durante seis años, pasó por tiempos oscuros luchando con el impacto mental de sus lesiones que le llevaron a dejar de ver fútbol. Sin embargo, la cirugía ya lo dejó libre de dolores y regresó a los All Whites el año pasado. \"Estoy muy feliz de volver a formar parte del grupo y de ser parte de algo más grande que el fútbol de clubes\", dijo a RNZ sobre sus esperanzas en la Copa del Mundo. El holandés-kiwi habla sólo holandés desde hace cinco años y en un ambiente de los All Whites se siente “un poco idiota” al tratar de conversar en inglés. \"Ya no soy exactamente un kiwi y eso me molesta un poco\", dice.", "en": "Arguably the most gifted Kiwi player in a generation, he has had a career blighted by knee injuries – leading to gruesome surgery requiring his knees to be broken and lowered. He was only 19 when he made his debut for the All Whites and also starred for PEC Zwolle as a teenager, scoring twice in its shock 5-1 defeat of Ajax in the 2014 Dutch Cup final. He moved to PSV Eindhoven but in his first week ruptured his ACL. Out of the national side for six years, he went through dark times struggling with the mental impact of his injuries which led to him not watching football anymore. However, the surgery has now made him pain-free and he returned to the All Whites last year. “I'm just really happy to be part of the group again and being a part of something bigger than just club football,” he told RNZ regarding his World Cup hopes. The Dutch-Kiwi has been speaking only Dutch for five years and in an All Whites’ setting feels “a little bit of an idiot”, trying to converse in English. “I'm not exactly a Kiwi anymore and it kind of annoys me,\" he says." }, special: "Comeback kid" },
  { number: 25, name: 'Lachlan Bayliss', position: 'MF', age: 23, club: 'Newcastle Jets', bio: { "es": "Bayliss sólo ganó su primer partido internacional en marzo con el entrenador, Darren Bazeley, diciendo que es \"un poco bólter\".  Bayliss ha superado el desafío de Bazeley de apuntar más alto después de haber jugado bien con la selección sub-23 de Nueva Zelanda en los Juegos Olímpicos de 2024. Bayliss ha tenido una temporada sobresaliente en la A-League con los Newcastle Jets, tanto asistiendo como marcando goles. \"Es un jugador apasionante, muy peligroso desde el banquillo\", afirmó el experto Paul Ifill. Nacido en Australia, califica a través de su difunto padre, que era kiwi. Jugar para los All Whites haría que su difunto padre estuviera \"muy orgulloso\", dice.  \"Significaría todo. Definitivamente siento una fuerte conexión con Nueva Zelanda a través de él\", dijo Bayliss a 1News.", "en": "Bayliss only won his first cap in March with the coach, Darren Bazeley, saying he’s “a bit of a bolter”.  Bayliss has met Bazeley’s challenge to aim higher after he played well for NZ Under-23s at the 2024 Olympics. Bayliss has had an outstanding season in the A-League with the Newcastle Jets, both assisting and scoring goals. “He’s an exciting player – very dangerous off the bench,” the pundit Paul Ifill said. Australian-born, he qualifies through his late father, who was a Kiwi. Playing for the All Whites would make his late father “very proud” he says.  “It would mean everything. I definitely feel a strong connection with New Zealand through him,” Bayliss told 1News." } },
  // Delanteros
  { number: 9, name: 'Chris Wood', position: 'FW', age: 34, club: 'Nottingham Forest', captain: true, bio: { "es": "Lo que Ronaldo es para Portugal, Wood lo es para los All Whites: goleador e infinitamente leal a su país, por lo que los fanáticos se han preocupado por su estado físico en la preparación de la Copa del Mundo. Una inspiración para los jóvenes, es \"el chico del cartel de los All Whites, definitivamente es el más destacado\", escribió el periodista de RNZ Matthew Nash antes de la lesión de rodilla que descarriló su última temporada en la Premier League. Wood tuvo una campaña sobresaliente en 2024-25, convirtiéndose en el primer jugador de Forest en 30 años en anotar más de 20 goles en una temporada y el primer Kiwi en ser elegido jugador del mes de la Premier League. El capitán más joven de la historia de los All Whites dice: \"Jugar para mi país me hace sentir extremadamente orgulloso y honrado\". Regresó de una cirugía de rodilla en abril y tiene la esperanza de permanecer en la cima por algún tiempo: \"No soy alguien con un ritmo vertiginoso, así que nunca voy a perder el ritmo. Así que es bueno llegar a una edad avanzada donde todavía puedo continuar haciendo lo que hacía cuando tenía 22 años\".", "en": "What Ronaldo is for Portugal, Wood is for the All Whites  - goalscorer and endlessly loyal to his country, so fans have been fretting about his fitness in the World Cup buildup. An inspiration for youngsters, he’s “the poster boy of the All Whites, he's definitely the standout”, RNZ journalist Matthew Nash wrote before the knee injury that derailed his latest Premier League season. Wood had an outstanding campaign in 2024-25, becoming the first Forest player in 30 years to score 20 plus goals in a season and the first Kiwi to be voted Premier League player of the month. The youngest ever All Whites captain says: “Playing for my country makes me extremely proud and honoured.” Returned from knee surgery in April and is hopeful of staying at the top for some time: “I'm not one with blistering pace, so I'm never gonna lose it. So that's good coming into my older years where I can actually still continue to do what I did when I was 22 years old.”" }, special: "Goal machine" },
  { number: 11, name: 'Eli Just', position: 'FW', age: 26, club: 'Motherwell', bio: { "es": "Just es de ascendencia china a través de su madre. A pesar de su pequeño cuerpo de 1,70 m, se siente cómodo con los cabezazos y es un atacante inteligente que prospera en espacios reducidos. A menudo se le utiliza en la banda derecha o como centrocampista ofensivo tanto para el club como para el país. Debutó con los All Whites con solo 19 años y dice que ha sido gratificante pasar de ser un aficionado a vestir la camiseta, especialmente tener a sus padres en las gradas cuando el equipo se clasificó para la Copa del Mundo contra Nueva Caledonia en marzo de 2025. Fue \"bastante especial\", dijo a RNZ. Fichar por Motherwell el año pasado fue otro paso importante para garantizar que su forma le ayudara a ganar la selección y tiempo de juego en la Copa del Mundo, dijo al sitio web Friends of Football.", "en": "Just is of Chinese descent through his mother. Despite his small 1.70m frame, he is comfortable with headers and is a smart attacker who thrives in tight spaces. He is often used on the right-wing or as an attacking midfielder for both club and country. He debuted for the All Whites at just 19 and says it has been rewarding to move from being a fan to wearing the strip, especially having his parents in the stand when the side qualified for the World Cup against New Caledonia in March 2025. It was “pretty special”, he told RNZ. Signing for Motherwell last year was another important step in ensuring his form would help him earn selection and game time at the World Cup, he told the Friends of Football website." } },
  { number: 17, name: 'Kosta Barbarouses', position: 'FW', age: 35, club: 'Western Sydney Wanderers', bio: { "es": "De ascendencia griega, Barbarouses es el segundo All White con más partidos internacionales del equipo después de Chris Wood y fue convocado por primera vez hace 18 años. Es el primer kiwi en marcar 100 goles en la A-League masculina, ha sido nombrado en el equipo masculino de la década de la A-League y ha ganado el campeonato con tres clubes diferentes. Su carrera comenzó cuando era un colegial de 17 años con el Wellington Phoenix en su temporada inaugural 2007-08 y ha regresado al club tres veces distintas, convirtiéndose en un favorito de los fanáticos. Le dijo a RNZ que una campaña para la Copa del Mundo tiene el costo de perderse los hitos de sus hijas, como comenzar la escuela, pero agregó que espera que lo entiendan cuando sean un poco mayores.", "en": "Of Greek heritage, Barbarouses is the second most capped All White in the squad after Chris Wood and was first called up 18 years ago. He’s the first Kiwi to score 100 goals in the men’s A-League, has been named in the A-League men’s team of the decade and has won the championship with three different clubs. His career started as a 17-year-old schoolboy with the Wellington Phoenix in their inaugural 2007–08 season and he has returned to the club three separate times, becoming a fan favourite. He told RNZ a World Cup campaign comes at the cost of missing his daughters’ milestones such as starting school but added that he hopes they will understand when they are a bit older." } },
  { number: 18, name: 'Ben Waine', position: 'FW', age: 24, club: 'Port Vale', bio: { "es": "Waine ha probado ambos lados de la vida como futbolista: marcó en su debut con la sub-20 y con los All Whites absolutos, pero también se sintió frustrado por la no selección a nivel de clubes y la sequía de goles. Ha recurrido a la experiencia de un psicólogo deportivo neozelandés para que le ayude a “profundizar”. \"Soy muy bueno en el aspecto mental del juego y trabajo mucho en eso\", le dijo a la BBC. Tener las herramientas para afrontar los tiempos difíciles ha sido “una ayuda enorme”, afirma. Durante su estancia en Plymouth Argyle, Waine jugó brevemente bajo las órdenes de la estrella de Inglaterra y del Manchester United, Wayne Rooney. Waine tiene una madre Geordie, por lo que es partidario del Newcastle United y le gusta el golf e ir a la playa. Llegó a los titulares en Inglaterra en marzo cuando su gol eliminó al Sunderland (de todos los clubes) en la quinta ronda de la Copa FA.", "en": "Waine has tasted both sides of life as a footballer – scoring on debut for the Under-20s and senior All Whites but also being frustrated by non-selection at club level and a goal drought. He has tapped into the expertise of a Kiwi sports psychologist to help him “dig in”. \"I'm big on the mental side of the game and I do a lot of work on that,” he told the BBC. Having the tools to cope with the hard times has been “a massive help”, he says. During his time at Plymouth Argyle, Waine briefly played under the orders of England and Manchester United star Wayne Rooney. Waine has a Geordie mother so he is a supporter of Newcastle United and enjoys golf and going to the beach. Hit the headlines in England in March when his goal eliminated Sunderland – of all clubs – in the FA Cup fifth round." }, special: "Interested in psychology" },
  { number: 19, name: 'Ben Old', position: 'FW', age: 23, club: 'St Étienne', bio: { "es": "En el contexto de Nueva Zelanda, Old es un talento poco común, según el periodista del NZ Herald, Michael Burgess, destacando el ritmo crudo, el control cercano y la capacidad del jugador para driblar a los jugadores. Las cualidades de Old lo convierten en un arma letal en el contraataque y es apenas el segundo neozelandés después de Bill Tuiloma que juega en la Ligue 1 de Francia, donde ha tenido que adaptarse a un estilo más agresivo y menos estructurado que el de su club neozelandés, el Phoenix. Los contratiempos incluyen una grave lesión en la rodilla y el descenso del equipo a la Ligue 2, pero la tranquilidad viene al meditar antes de los partidos para utilizar algunos de sus mejores momentos como inspiración. En lugar de la sesión de fotos que esperaba al unirse a St Étienne, un artista lo pintó. \"Fue una experiencia realmente asombrosa y un recuerdo que recordaré para siempre\", dijo a la revista Channel. Dato curioso: Old fue un niño prodigio en el golf, visitó los EE. UU. con solo siete años para competir contra otros jóvenes talentos y espera jugar en los mejores campos del Reino Unido como parte de su deseo de aliviar las presiones del fútbol de primer nivel.", "en": "In the New Zealand context Old is a rare talent, according to the NZ Herald journalist Michael Burgess, highlighting the player’s raw pace, close control and ability to dribble past players. Old’s assets make him a lethal weapon on the counter attack and he is only the second New Zealander after Bill Tuiloma to play in France’s Ligue 1, where he has had to adjust to a more aggressive, less structured style than his Kiwi club the Phoenix. Setbacks have included a serious knee injury and the side’s relegation to Ligue 2 – but peace of mind comes with meditating before matches to use some of his best moments for inspiration. Instead of the photo shoot he was expecting on joining St Étienne an artist painted him. “It was a truly amazing experience and a memory I’ll remember forever,” he told Channel magazine. Fun Fact: Old was a child prodigy at golf, visiting the US aged just seven to compete against other young talents, and he hopes to play at the UK’s top courses as part of his desire to relieve the pressures of top class football." }, special: "Golf child prodigy" },
  { number: 20, name: 'Callum McCowatt', position: 'FW', age: 27, club: 'Silkeborg', bio: { "es": "Fue elegido jugador del Silkeborg de la temporada 2025 por los aficionados, además de ser el máximo goleador del club en todas las competiciones. ¿La principal diferencia que ha notado al vivir seis años en Escandinavia? \"Los jugadores son mucho más fuertes mentalmente y es evidente desde el momento en que entras por la puerta, que es algo en lo que creo que los jugadores de Nueva Zelanda deberían trabajar, incluido yo mismo. He tardado años [trabajando en ello] y es algo en lo que todavía estoy trabajando activamente\", le dijo a Stuff. Después de avanzar por las categorías de edad de Nueva Zelanda, jugó su primer partido internacional en 2019 y marcó un gol en su debut contra Irlanda. Se ha adaptado a la vida en Dinamarca, donde “ahora se siente como en casa”, y es un admirador de cómo se trata a la gente y está en camino de dominar el idioma. “Creo que tal vez llegué siendo un niño y ahora soy un hombre”, dice.", "en": "Was voted Silkeborg player of the 2025 season by fans as well as being the club’s top scorer in all competitions. The main difference he’s noticed being based for six years in Scandinavia? “Players are much more mentally stronger and it's evident from the moment you walk in the door, which is something that I think New Zealand players should work on – myself included. I've taken years [working on it] and it's something I'm working on actively still,” he told Stuff. After moving through the age-group levels for New Zealand, he got his first cap in 2019 and scored a goal on debut against Ireland. He has taken to life in Denmark, which “feels like home now”, and is an admirer of how people are treated and is on the way to becoming fluent in the language. “I think maybe I've come as a boy and I'm a man now,” he says." } },
  { number: 21, name: 'Jesse Randall', position: 'FW', age: 23, club: 'Auckland FC', bio: { "es": "Poder jugar en ataque y en banda ha ayudado a impulsar a la estrella en ascenso con siete partidos internacionales al equipo de la Copa del Mundo. Su excelente forma con el Auckland FC en la A-League, incluido el hecho de ser su máximo goleador en la última campaña, también ayudó a su causa. Califica su ritmo como su mejor baza. La carrera de Randall ahora está despegando después de un comienzo lento: nunca una academia en su ciudad natal, Wellington, se acercó a él y los juicios en Inglaterra fueron \"bastante despiadados\", dijo a Stuff. Un período con Charleston en los EE. UU. no le dio mucho tiempo de juego y, a medida que crecieron las dudas, su carrera solo revivió con una convocatoria tardía del entrenador de los All Whites, Darren Bazeley, para unirse a su equipo Sub-23 para los Juegos Olímpicos de París. Después de la Copa del Mundo, Randall estará obligado a Escocia a iniciar un contrato de dos años con el Dundee United. Dato curioso: Randall tenía solo siete años cuando asistió al partido contra Bahréin en el que Nueva Zelanda aseguró su última clasificación para la Copa del Mundo en 2009. \"Ese fue un momento enorme para mí, saber que lo que quería hacer era jugar al fútbol\".", "en": "Being able to play in attack and on the wing has helped propel the seven-cap rising star into the World Cup squad. His excellent form with Auckland FC in the A-League, including being their top goalscorer in the latest campaign, also helped his cause. He rates his pace as his best asset. Randall’s career is now taking off after a slow start – he was never approached by an academy in his home city, Wellington, and trials in England were “pretty ruthless”, he told Stuff. A spell with Charleston in the US didn’t lead to much game time and as the doubts grew, his career was only revived by a late call-up from All Whites coach Darren Bazeley to join his Under-23 squad for the Paris Olympics. After the World Cup Randall will be Scotland bound to start a two-year contract with Dundee United. Fun fact: Randall was just seven when he attended the match against Bahrain that saw NZ secure their last World Cup qualification in 2009. “That was a massive moment for me, knowing that’s what I wanted to do is play football.”" }, special: "Surprise call-up" },
];

export const lineup = {
  formation: '4-3-3',
  startingXI: [1, 13, 5, 4, 2, 6, 8, 7, 19, 9, 11]
};
